float bscale=100.0;
const float pi=3.14159265359;

const int STEPS=10;

float smoothlerp (float a, float b, float x) {
   float t = x * x * (3.0f - 2.0f * x);

   return a + t*(b-a);
}
float hash(vec2 seed){
    vec2 M1=vec2(3.1251,17.8737);
    float M2=43758.545312;
    return fract(sin(dot(seed,M1))*M2)*2.0-1.0;
}

float perlin(vec2 point, float scale){
    vec2 block=floor(point/scale)*scale/iResolution.xy;
    vec2 dis=fract(point/scale);

    vec2 t=scale/iResolution.xy;
    /*
    vec2 v1=normalize(vec2(hash(block),hash(block+vec2(1.0))));
    vec2 v2=normalize(vec2(hash(block+vec2(t.x,0.0)),hash(block+vec2(t.x,0.0)+vec2(1.0))));
    vec2 v3=normalize(vec2(hash(block+vec2(0.0,t.y)),hash(block+vec2(0.0,t.y)+vec2(1.0))));
    vec2 v4=normalize(vec2(hash(block+vec2(t.x,t.y)),hash(block+vec2(t.x,t.y)+vec2(1.0))));
    */
    float a1=hash(block)*pi;
    vec2 v1=vec2(cos(a1),sin(a1));
    float a2=hash(block+vec2(t.x,0.0))*pi;
    vec2 v2=vec2(cos(a2),sin(a2));
    float a3=hash(block+vec2(0.0,t.y))*pi;
    vec2 v3=vec2(cos(a3),sin(a3));
    float a4=hash(block+vec2(t.x,t.y))*pi;
    vec2 v4=vec2(cos(a4),sin(a4));

    float d1=dot(dis,v1);
    float d2=dot(dis-vec2(1.0,0.0),v2);
    float d3=dot(dis-vec2(0.0,1.0),v3);
    float d4=dot(dis-vec2(1.0,1.0),v4);


    return smoothlerp(smoothlerp(d1,d2,dis.x),smoothlerp(d3,d4,dis.x),dis.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float col=0.0;
    float intensity=1.0;
    for (int i=0; i<STEPS; i++){
        col+=perlin(fragCoord,bscale);
        intensity/=2.0;
        bscale/=2.0;
    }
    // Output to screen
    fragColor = vec4(col,col,col,1.0);
}
